cd /workspace && cat > /tmp/repro.py <<'EOF'
import numpy as np
print(np.__version__, np.__file__)
a = np.array([44, 47, 64, 67, 67, 9, 83, 21, 36, 87], dtype='timedelta64[s]')
b = np.array([70, 88, 88, 12, 58, 65, 39, 87, 46, 88], dtype='timedelta64[s]')
print("issubdtype timedelta, integer:", np.issubdtype(a.dtype, np.integer))
try:
    print(np.in1d(a, b))
except Exception as e:
    print("kind=None:", type(e).__name__, e)
try:
    print(np.in1d(a, b, kind='table'))
except Exception as e:
    print("kind=table:", type(e).__name__, e)
try:
    print(np.in1d(a, b, kind='sort'))
except Exception as e:
    print("kind=sort:", type(e).__name__, e)
EOF
python /tmp/repro.py
